    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The hosts named in this node's `HTTPClient<[...]>` grant. The host-side
/// handle enforces this list too (and traps on violation); checking here lets
/// an off-list subscription be reported as a failure instead of killing the run.
const ALLOWED_HOSTS: &[&str] = &[
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the lowercase host of an http(s) URL, or `None` if the URL is not
/// a plain http/https URL with a DNS-style host.
fn host_of(url: &str) -> Option<String> {
    let trimmed = url.trim();
    let lower = trimmed.to_ascii_lowercase();
    let rest = if let Some(r) = lower.strip_prefix("https://") {
        r
    } else if let Some(r) = lower.strip_prefix("http://") {
        r
    } else {
        return None;
    };

    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];

    // Drop any userinfo.
    let hostport = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };

    // IPv6 literals are never on the allowlist.
    if hostport.starts_with('[') {
        return None;
    }

    let host = match hostport.find(':') {
        Some(i) => {
            let port = &hostport[i + 1..];
            if !port.is_empty() && !port.bytes().all(|b| b.is_ascii_digit()) {
                return None;
            }
            &hostport[..i]
        }
        None => hostport,
    };

    let host = host.strip_suffix('.').unwrap_or(host);
    if host.is_empty() {
        return None;
    }
    Some(host.to_string())
}

fn is_allowed(url: &str) -> bool {
    match host_of(url) {
        Some(h) => ALLOWED_HOSTS.iter().any(|a| *a == h),
        None => false,
    }
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            if !is_allowed(&url) {
                failures.push(FetchFailure {
                    url,
                    error: String::from("host not in this node's HTTP allowlist"),
                });
                continue;
            }

            match http_client::fetch(url.trim()) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
```

